    def booking_hotels(
        self,
        location: str,
        *,
        checkin: Optional[str] = None,
        checkout: Optional[str] = None,
        adults: Optional[int] = None,
        children: Optional[int] = None,
        rooms: Optional[int] = None,
        currency: Optional[str] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Booking.com hotels.

        Searches Booking.com for `location` and returns the properties as JSON:
        `name`, `price` (with `checkin`/`checkout`), `reviewScore`, `address`,
        coordinates, `image` and a hotel `url`. Set `adults`, `children`,
        `rooms` and `currency`, and collect up to `max_results` across pages.
        Prices only appear when check-in/check-out dates are given.

        Args:
            location: City or place to search, e.g. 'Austin' or 'Paris'.
            checkin: Check-in YYYY-MM-DD (needed for prices).
            checkout: Check-out YYYY-MM-DD.
            adults: Number of adults.
            children: Number of children.
            rooms: Number of rooms.
            currency: Price currency: USD, EUR, GBP, AUD, CAD, CHF, JPY, CNY,
                INR, BRL, MXN, PLN, SEK, NOK, DKK, AED, SGD, ZAR, TRY, RUB. API
                default: USD.
            max_results: How many properties to collect across pages. API
                default: 25.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE').

        Calls ``POST /travel/booking``.
        """
        return self._post_json(
            "/travel/booking",
            location=location,
            checkin=checkin,
            checkout=checkout,
            adults=adults,
            children=children,
            rooms=rooms,
            currency=currency,
            max_results=max_results,
            proxy_country=proxy_country,
        )

    def booking_reviews(
        self,
        hotel: str,
        *,
        languages: Optional[str] = None,
        max_results: Optional[int] = None,
        since: Optional[str] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Booking.com hotel reviews.

        Given a Booking.com `hotel` (page URL or `<cc>/<slug>`), returns its
        newest guest `reviews`: `id`, `reviewDate`, `rating`, `ratingText`,
        `title`, `ratingBand`, `positiveText`, `negativeText`, `reviewer`
        (`name`, `country`, `countryCode`), `tripType`, `travelerType`,
        `nights`, `stayMonth`, `helpfulVotes`, `submittedFromMobile`,
        `language` and the raw `tags`. Booking serves the newest 15 reviews
        written in each language: pick the languages with `languages` (or
        `all`), cap the total with `max_results` and drop older reviews with
        `since`. Billed one unit per language page fetched (`pagesFetched`).

        Args:
            hotel: Booking.com hotel page URL, e.g.
                https://www.booking.com/hotel/fr/le-meurice.html (a locale
                suffix such as .en-gb.html and query parameters are fine), or
                `<cc>/<slug>` such as fr/le-meurice.
            languages: Review languages to read, comma-separated, or `all`: en,
                de, fr, es, it, nl, pt, pl, ru, ja, zh, ko, sv, da, no, fi, cs,
                tr. Default en. Booking serves the newest 15 reviews written in
                each language; each language is one page and one billed unit,
                fetched in the order given until max_results is reached.
            max_results: How many reviews to return across languages (1-270, at
                most 15 per language). API default: 15.
            since: Only reviews written on or after this date (YYYY-MM-DD).
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE').

        Calls ``POST /travel/booking-reviews``.
        """
        return self._post_json(
            "/travel/booking-reviews",
            hotel=hotel,
            languages=languages,
            max_results=max_results,
            since=since,
            proxy_country=proxy_country,
        )

    def airbnb_search(
        self,
        location: str,
        *,
        checkin: Optional[str] = None,
        checkout: Optional[str] = None,
        adults: Optional[int] = None,
        room_type: Optional[str] = None,
        min_price: Optional[int] = None,
        max_price: Optional[int] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Airbnb stay listings.

        Searches Airbnb for `location` and returns the stay listings as JSON:
        `name`, `roomType`, `price` (USD by default) with any original price,
        `rating` and `reviewCount`, coordinates, `badges` (e.g. Guest
        favourite), `image` and a clean room `url`. Filter with
        `checkin`/`checkout`, `adults`, `min_price`/`max_price` and
        `room_type`, and collect up to `max_results` across pages.

        Args:
            location: City to search, e.g. 'Austin, TX' or 'Paris, France'.
            checkin: Check-in date YYYY-MM-DD (with checkout).
            checkout: Check-out date YYYY-MM-DD (with checkin).
            adults: Number of adult guests.
            room_type: Room type filter: entire_home, private_room, hotel_room,
                shared_room. Omit for all.
            min_price: Minimum nightly price.
            max_price: Maximum nightly price.
            max_results: How many listings to collect across pages. API
                default: 48.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Defaults to US so prices are in USD.

        Calls ``POST /travel/airbnb``.
        """
        return self._post_json(
            "/travel/airbnb",
            location=location,
            checkin=checkin,
            checkout=checkout,
            adults=adults,
            room_type=room_type,
            min_price=min_price,
            max_price=max_price,
            max_results=max_results,
            proxy_country=proxy_country,
        )

