    def zillow_search(
        self,
        location: str,
        *,
        status: Optional[str] = None,
        max_results: Optional[int] = None,
        page: Optional[int] = None,
        sort: Optional[str] = None,
        home_type: Optional[str] = None,
        min_price: Optional[int] = None,
        max_price: Optional[int] = None,
        beds: Optional[int] = None,
        baths: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Zillow real-estate listings.

        Searches Zillow for `location` (a city/state or ZIP) and returns the
        listings as JSON: `price`, `beds`, `baths`, `area`, `address`,
        `homeType`, `zestimate`, `rentZestimate`, `daysOnZillow`, coordinates,
        broker and a clean `url`. Filter with `status` (for_sale / for_rent /
        sold), `min_price`/`max_price`, `beds`, `baths` and `home_type`, sort
        with `sort`, and collect up to `max_results` across pages. Rental
        results can include apartment buildings (`isBuilding: true`): they have
        no `zpid` and carry `lotId`, `buildingName`, a rent range (`price` to
        `maxPrice`), `units` and `availableUnits` instead.

        Args:
            location: City/state or ZIP to search, e.g. 'Austin, TX' or
                '78704'.
            status: Listing status: for_sale, for_rent, sold. API default:
                for_sale.
            max_results: How many listings to collect across pages (~41 per
                page). API default: 41.
            page: 1-based results page to start from. API default: 1.
            sort: Ordering: newest, price_asc, price_desc, relevant, beds,
                sqft, lot. API default: newest.
            home_type: Property type filter: houses, condos, townhomes,
                multi_family, apartments, manufactured, lots_land. Omit for
                all.
            min_price: Minimum price (or monthly rent).
            max_price: Maximum price (or monthly rent).
            beds: Minimum bedrooms.
            baths: Minimum bathrooms.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Defaults to US.

        Calls ``POST /realestate/zillow``.
        """
        return self._post_json(
            "/realestate/zillow",
            location=location,
            status=status,
            max_results=max_results,
            page=page,
            sort=sort,
            home_type=home_type,
            min_price=min_price,
            max_price=max_price,
            beds=beds,
            baths=baths,
            proxy_country=proxy_country,
        )

    def zillow_detail(
        self,
        *,
        url: Optional[str] = None,
        zpid: Optional[str] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape a single Zillow property's full detail.

        Fetches one Zillow property (by `url` or `zpid`) and returns the full
        record as JSON: `price`, `zestimate`, `rentZestimate`, `beds`, `baths`,
        `area`, `lotSize`, `yearBuilt`, `homeType`, `status`, `description`,
        `priceHistory`, `taxHistory`, `schools`, `facts`, `parking`, listing
        `brokerName`/`listingAgent`, `mlsid`, `monthlyHoaFee`, `pricePerSqft`,
        `daysOnZillow`, `taxAssessedValue`, coordinates, the `photos` gallery
        and `virtualTourUrl`. Every field is always present and is `null` when
        Zillow does not show it for that listing (for-sale and sold pages carry
        fewer sections than rentals). Companion to the Zillow search plugin
        (`/realestate/zillow`).

        Args:
            url: Zillow property URL, e.g.
                'https://www.zillow.com/homedetails/.../29432984_zpid/'. Either
                url or zpid is required.
            zpid: Zillow property id (zpid), e.g. '29432984'. Alternative to
                url.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank to let the API pick.

        Calls ``POST /realestate/zillow-detail``.
        """
        return self._post_json(
            "/realestate/zillow-detail",
            url=url,
            zpid=zpid,
            proxy_country=proxy_country,
        )

