    def rightmove_search(
        self,
        location: str,
        *,
        channel: Optional[str] = None,
        min_price: Optional[int] = None,
        max_price: Optional[int] = None,
        min_bedrooms: Optional[int] = None,
        max_bedrooms: Optional[int] = None,
        property_type: Optional[str] = None,
        sort: Optional[str] = None,
        max_results: Optional[int] = None,
        page: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Rightmove property listings.

        Searches Rightmove (the UK's largest property portal) for `location`
        and returns the listings as JSON: `address`, `price` (`amount` +
        `currency` + `display` + `frequency`), `transactionType`, `bedrooms`,
        `bathrooms`, `propertyType`, `summary`, `coordinates`, `images`,
        `agent` (name / branch / phone) and listing dates. Filter with
        `channel` (buy / rent), `min_price`/`max_price`,
        `min_bedrooms`/`max_bedrooms` and `property_type`, sort with `sort`,
        and collect up to `max_results` across pages.

        Args:
            location: UK place name, e.g. 'London', 'Manchester', 'Milton
                Keynes'.
            channel: buy (for sale) or rent (to rent). API default: buy.
            min_price: Minimum price (GBP).
            max_price: Maximum price (GBP).
            min_bedrooms: Minimum bedrooms.
            max_bedrooms: Maximum bedrooms.
            property_type: Rightmove property types, comma-separated, e.g.
                'flat,detached'.
            sort: Ordering: relevance, newest, price_asc, price_desc, oldest.
                API default: relevance.
            max_results: How many listings to collect across pages (~24 per
                page, max 1008). API default: 48.
            page: 1-based results page to start from. API default: 1.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank to let the API pick.

        Calls ``POST /realestate/rightmove``.
        """
        return self._post_json(
            "/realestate/rightmove",
            location=location,
            channel=channel,
            min_price=min_price,
            max_price=max_price,
            min_bedrooms=min_bedrooms,
            max_bedrooms=max_bedrooms,
            property_type=property_type,
            sort=sort,
            max_results=max_results,
            page=page,
            proxy_country=proxy_country,
        )

    def idealista_search(
        self,
        location: str,
        *,
        url: Optional[str] = None,
        country: Optional[str] = None,
        operation: Optional[str] = None,
        property_type: Optional[str] = None,
        min_price: Optional[int] = None,
        max_price: Optional[int] = None,
        min_size: Optional[int] = None,
        max_size: Optional[int] = None,
        rooms: Optional[str] = None,
        bathrooms: Optional[str] = None,
        features: Optional[str] = None,
        sort: Optional[str] = None,
        page: Optional[int] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape idealista property listings (Spain, Italy, Portugal).

        Searches idealista (idealista.com, idealista.it, idealista.pt) for
        `location` - or takes any idealista search `url` - and returns the
        listings as JSON: `id`, `url`, `title`, `price` + `currency` (+
        `pricePeriod` for rentals), `originalPrice` and `priceDropPercent`
        after a price cut, `pricePerM2`, `area`, `rooms`, `floor`, `lift`,
        `exterior`, `parking`, `description`, `tags`, `images`, `imageCount`,
        `multimedia` (plan, video, 3D tour), `agency` and `professional`.
        Filter by `operation` (sale / rent), `property_type`, price and size
        ranges, `rooms`, `bathrooms` and `features`, order with `sort`, and
        collect up to `max_results` across pages (30 per page; idealista shows
        at most 60 pages per search). A search with no match answers 200 with
        an empty `listings`. Billed one unit per page fetched (`pagesFetched`).

        Args:
            location: Location as idealista writes it in its URLs: a
                municipality ('madrid-madrid', 'barcelona-barcelona', 'milano-
                milano', 'lisboa'), a district ('madrid/centro',
                'lisboa/arroios') or a province ('malaga-provincia'). Required
                unless url is given.
            url: Any idealista search URL (idealista.com, idealista.it or
                idealista.pt) with its filters, e.g.
                https://www.idealista.com/alquiler-viviendas/barcelona-
                barcelona/con-precio-hasta_2000,de-dos-dormitorios/. Overrides
                location and the filter parameters.
            country: es, it, pt (idealista.com / .it / .pt). API default: es.
            operation: sale or rent. API default: sale.
            property_type: One of: homes, new_homes, offices, premises,
                garages, lands, storage, buildings, rooms. API default: homes.
            min_price: Minimum price in EUR (monthly rent with operation=rent).
            max_price: Maximum price in EUR.
            min_size: Minimum area in m².
            max_size: Maximum area in m².
            rooms: Comma-separated room counts: bedrooms in Spain (0 = studio
                ... 4 = four or more) and Portugal (T0 ... T4+), total rooms in
                Italy (1 ... 5 = five or more). E.g. '2,3'.
            bathrooms: Comma-separated 1, 2, 3 (3 = three or more).
            features: Comma-separated: lift, terrace, balcony, garage, pool,
                garden, air_conditioning, storage_room, fitted_wardrobes,
                accessible, luxury, new_construction, good_condition,
                to_renovate.
            sort: One of: relevance, price_asc, price_desc, newest, oldest,
                size_asc, size_desc, price_per_m2_asc, price_per_m2_desc,
                biggest_drop. API default: relevance.
            page: 1-based results page to start from (30 listings per page, at
                most 60). Use the `nextPage` of a previous response to
                continue.
            max_results: How many listings to collect across pages (1-300);
                each page fetched is one billed unit. API default: 30.
            proxy_country: Proxy country the request is sent from (ISO-2).
                Leave blank for the exit chosen for the site.

        Calls ``POST /realestate/idealista``.
        """
        return self._post_json(
            "/realestate/idealista",
            location=location,
            url=url,
            country=country,
            operation=operation,
            property_type=property_type,
            min_price=min_price,
            max_price=max_price,
            min_size=min_size,
            max_size=max_size,
            rooms=rooms,
            bathrooms=bathrooms,
            features=features,
            sort=sort,
            page=page,
            max_results=max_results,
            proxy_country=proxy_country,
        )

    def idealista_detail(
        self,
        listing: str,
        *,
        country: Optional[str] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape one idealista listing (Spain, Italy, Portugal).

        Given an idealista `listing` id (with `country`) or URL, returns the
        listing as JSON: `title`, `locationLine`, `operation`, `propertyType`,
        `price` + `currency` (+ `pricePeriod`),
        `originalPrice`/`priceDropPercent`, `pricePerM2`, `priceDetails` (the
        price breakdown idealista shows, e.g. community fees or deposit),
        `area`, `usableArea`, `rooms`, `bathrooms`, `floor`, `lift`,
        `builtYear`, `energyRating`, `features` (every feature group idealista
        lists), `description`, `address`, `coordinates` (`locationApproximate`
        when the advertiser hid the exact spot), `images`, `floorPlans`,
        `multimediaCounts`, `advertiser` (name, type, reference, agency page)
        and `updated`. A listing its advertiser removed answers 404. Billed one
        unit.

        Args:
            listing: idealista listing id ('111278716') or URL, e.g.
                https://www.idealista.com/inmueble/111278716/,
                https://www.idealista.it/immobile/37068709/ or
                https://www.idealista.pt/imovel/34868387/.
            country: Country of a bare listing id: es, it, pt. Ignored for a
                URL. API default: es.
            proxy_country: Proxy country the request is sent from (ISO-2).
                Leave blank for the exit chosen for the site.

        Calls ``POST /realestate/idealista-detail``.
        """
        return self._post_json(
            "/realestate/idealista-detail",
            listing=listing,
            country=country,
            proxy_country=proxy_country,
        )

