    def mobile_de(
        self,
        make: Optional[str] = None,
        *,
        make_id: Optional[int] = None,
        model: Optional[str] = None,
        price_min: Optional[int] = None,
        price_max: Optional[int] = None,
        year_min: Optional[int] = None,
        mileage_max: Optional[int] = None,
        fuel: Optional[str] = None,
        max_results: Optional[int] = None,
        page: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape mobile.de car listings.

        Searches mobile.de (Germany's largest car marketplace) and returns the
        result-list cards as JSON: `title`, `makeModel`, `price` (numeric EUR)
        plus `priceFormatted`, `firstRegistration`, `mileage`, `power` (`kw` +
        `ps`), `fuel`, and the detail `id` + `url`. Pass a friendly `make` name
        (or a raw `make_id`), and filter with `price_min`/`price_max`,
        `year_min`, `mileage_max` and `fuel`; collect up to `max_results`
        across pages. `model` is accepted as free text but is not used to
        filter (mobile.de needs a numeric model id we do not resolve).

        Args:
            make: Make name, e.g. 'bmw', 'volkswagen', 'audi'. Required unless
                `make_id` is given.
            make_id: Raw mobile.de numeric make id, overrides `make` (e.g. 3500
                = BMW).
            model: Model name (free text). Model-id resolution is not
                available, so it is used only as a note; results are not
                filtered by model.
            price_min: Minimum price in EUR.
            price_max: Maximum price in EUR.
            year_min: Earliest first-registration year (YYYY).
            mileage_max: Maximum mileage in km.
            fuel: Fuel: petrol, diesel, electric, hybrid (or a raw mobile.de
                code).
            max_results: How many listings to collect across pages (~20 per
                page). API default: 20.
            page: 1-based results page to start from. API default: 1.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank to let the API pick.

        Calls ``POST /vehicles/mobile-de``.
        """
        return self._post_json(
            "/vehicles/mobile-de",
            make=make,
            make_id=make_id,
            model=model,
            price_min=price_min,
            price_max=price_max,
            year_min=year_min,
            mileage_max=mileage_max,
            fuel=fuel,
            max_results=max_results,
            page=page,
            proxy_country=proxy_country,
        )

