    def indeed_jobs(
        self,
        query: str,
        *,
        country: Optional[str] = None,
        location: Optional[str] = None,
        radius: Optional[int] = None,
        job_type: Optional[str] = None,
        days: Optional[int] = None,
        remote: Optional[bool] = None,
        sort: Optional[str] = None,
        max_results: Optional[int] = None,
        start: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Indeed job listings.

        Searches Indeed for `query` in `location` and returns the job listings
        as JSON: `title`, `company`, `location`, `salary` (with parsed
        `min`/`max`), `jobTypes`, `companyRating`, a `snippet`, `datePosted`
        (YYYY-MM-DD), `sponsored` (Indeed's paid placement) and a clean job
        `url`. Filter with `country`, `job_type`, `days` (posting age),
        `remote`, sort with `sort` (`date` returns the collected jobs newest
        first, sponsored ones included), and collect up to `max_results` across
        pages. Indeed sits behind Cloudflare + PerimeterX - handled for you.

        Args:
            query: What to search, e.g. 'software engineer' or 'nurse'.
            country: Indeed country site: us, uk, ca, au, in, ie, de, fr, nl,
                es, it, at, ch, be, pl, se, sg, za, nz, mx. API default: us.
            location: Where, e.g. 'Austin, TX' or 'London'.
            radius: Search radius in miles/km around the location.
            job_type: Job type: fulltime, parttime, contract, internship,
                temporary.
            days: Max posting age in days: 1, 3, 7, 14.
            remote: Only remote jobs. API default: false.
            sort: Ordering: relevance, date. API default: relevance.
            max_results: How many jobs to collect across pages. API default:
                30.
            start: 0-based result offset to start from. API default: 0.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Defaults to the country's site.

        Calls ``POST /jobs/indeed``.
        """
        return self._post_json(
            "/jobs/indeed",
            query=query,
            country=country,
            location=location,
            radius=radius,
            job_type=job_type,
            days=days,
            remote=remote,
            sort=sort,
            max_results=max_results,
            start=start,
            proxy_country=proxy_country,
        )

    def glassdoor_jobs(
        self,
        keyword: str,
        *,
        location: Optional[str] = None,
        loc_id: Optional[int] = None,
        loc_type: Optional[str] = None,
        sort: Optional[str] = None,
        job_type: Optional[str] = None,
        experience: Optional[str] = None,
        from_age: Optional[int] = None,
        min_salary: Optional[int] = None,
        remote: Optional[bool] = None,
        radius: Optional[int] = None,
        max_results: Optional[int] = None,
        page: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Glassdoor job listings.

        Searches Glassdoor for `keyword` and returns the job listings as JSON:
        `title`, `jobId`, `url`, `company` (+ `companyId`, `companyRating`,
        `companyLogo`), `location`, `ageInDays`, `salary` (p10/median/p90,
        payPeriod, currency, source), `snippet`, `skills`, `easyApply` and
        `sponsored`. Filter with `location`, `from_age`, `job_type`,
        `min_salary`, `experience` and `remote`, sort with `sort` (recency /
        relevance), and collect up to `max_results` across pages.

        Args:
            keyword: Job title / keywords to search, e.g. 'software engineer'.
            location: Location name to filter by, e.g. 'New York, NY'. Resolved
                to Glassdoor's location id automatically; pass loc_id to skip
                resolution. A name Glassdoor does not know is a 400.
            loc_id: Glassdoor numeric location id (overrides `location`
                resolution).
            loc_type: Location type for loc_id: C=city, S=state, N=nation,
                M=metro.
            sort: Ordering: recency, relevance. API default: recency.
            job_type: Employment type: fulltime, parttime, contract,
                internship, temporary, apprenticeship. Omit for any.
            experience: Experience level: internship, entrylevel,
                midseniorlevel, director, executive. Omit for any.
            from_age: Posted within N days (1, 3, 7, 14 or 30).
            min_salary: Minimum annual salary.
            remote: Remote jobs only. API default: false.
            radius: Search radius in miles around the location.
            max_results: How many jobs to collect across pages (~30 per page).
                API default: 30.
            page: 1-based results page to start from. API default: 1.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Defaults to US.

        Calls ``POST /jobs/glassdoor``.
        """
        return self._post_json(
            "/jobs/glassdoor",
            keyword=keyword,
            location=location,
            loc_id=loc_id,
            loc_type=loc_type,
            sort=sort,
            job_type=job_type,
            experience=experience,
            from_age=from_age,
            min_salary=min_salary,
            remote=remote,
            radius=radius,
            max_results=max_results,
            page=page,
            proxy_country=proxy_country,
        )

    def glassdoor_reviews(
        self,
        company: str,
        *,
        sort: Optional[str] = None,
        rating: Optional[int] = None,
        job_title: Optional[str] = None,
        keyword: Optional[str] = None,
        topic: Optional[str] = None,
        employment_status: Optional[str] = None,
        language: Optional[str] = None,
        current_only: Optional[bool] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Glassdoor company reviews.

        Returns a company's Glassdoor employee reviews as JSON. Each review has
        `id`, `url`, `title`, `rating` (1-5), `subratings` (work/life balance,
        culture and values, diversity and inclusion, career opportunities,
        compensation and benefits, senior management), `recommendToFriend`,
        `ceoApproval`, `businessOutlook`, `pros`, `cons`, `advice`, `jobTitle`,
        `employmentStatus`, `isCurrentEmployee`, `yearsOfEmployment`,
        `location`, `date`, `helpfulCount`, `notHelpfulCount`, `featured`,
        `employerResponse` and `view` (the sort / filter view it came from).
        The response also carries `summary` (overall rating, review counts,
        recommend / CEO approval / business outlook percentages, the CEO, sub-
        rating averages, star distribution, reviews in the last 7 and 30 days),
        `companyMeta` (name, logo, website, industry, sector, headquarters,
        size) and `totalReviews`. The counts are Glassdoor's own and measure
        different sets: `totalReviews` is the number of reviews matching every
        filter of the call (`rating`, `job_title`, `keyword`, `topic`,
        `employment_status`, `language`, `current_only`; the default view is
        English reviews by full-time and part-time employees), the set the
        views read from. `summary.allReviewsCount` is every review Glassdoor
        holds for the employer, rated or not, in any language and employment
        status; no filter changes it. `summary.reviewCount` is the number of
        ratings behind `summary.overallRating`, and `summary.ratedReviewsCount`
        the number of reviews that carry a star rating; Glassdoor counts the
        two separately, so they can differ by a few. Both follow `rating` but
        not the language or employment filters, so they are usually above
        `totalReviews`. `summary.ratingDistribution` holds the star counts
        Glassdoor sends for its rating bars (`overall`, each sub-rating, and
        `recommendToFriend`); for employers with many reviews they cover only
        part of them (Google: 18,643 overall against a `reviewCount` of
        52,845), so read them as proportions, not totals, and with `rating` set
        only that star is counted. `summary.reviewsLast7Days` and
        `reviewsLast30Days` count reviews matching the filters. Give `company`
        as a Glassdoor employer id, a Glassdoor company URL or a company name.
        Only US proxies are used (`proxy_country` accepts US or blank):
        Glassdoor redirects other countries to their local site, where these
        pages do not exist. Glassdoor shows anonymous visitors only the first
        page (3 reviews) of each sort / filter view and redirects deeper pages
        to sign-in, so there is no page parameter: use `sort`, `rating` and the
        filters to reach other reviews, or raise `max_results` to read several
        views in one call. `hasMore` is always false and `nextPage` null;
        `publicLimitReached` is true when fewer reviews came back than asked
        because the views anonymous visitors may read ran out. Every field is
        always present and is `null` when Glassdoor does not show it. Billed
        per review view fetched (`pagesFetched`).

        Args:
            company: The company: a Glassdoor employer id (e.g. '9079'), any
                Glassdoor company URL (e.g.
                'https://www.glassdoor.com/Reviews/Google-Reviews-E9079.htm'),
                or a company name (e.g. 'Bank of America', matched with
                Glassdoor's company search).
            sort: Review order: recent, helpful, highest, lowest. API default:
                recent.
            rating: Only reviews with this overall star rating (1-5).
            job_title: Only reviews from job titles matching this text, e.g.
                'software engineer' (Glassdoor's own job-title search).
            keyword: Only reviews mentioning this keyword, e.g. 'remote'.
            topic: Only reviews about one topic: compensation, culture,
                career_development, management, work_life_balance,
                diversity_and_inclusion.
            employment_status: Comma list of full_time, part_time, contract,
                intern, freelance. Defaults to Glassdoor's own view:
                full_time,part_time.
            language: Comma list of review languages (ISO 639-3): eng, fra,
                deu, nld, por, spa, ita. Defaults to eng.
            current_only: Only reviews by current employees. API default:
                false.
            max_results: How many reviews to return. Glassdoor shows anonymous
                visitors 3 reviews per view; above that the call also reads the
                other sort orders and each star rating, and merges the distinct
                reviews. API default: 3.
            proxy_country: Proxy country the request is sent from. Only US (or
                blank, the default) is accepted: Glassdoor redirects visitors
                from other countries to their local site, where the English
                reviews pages do not exist.

        Calls ``POST /reviews/glassdoor``.
        """
        return self._post_json(
            "/reviews/glassdoor",
            company=company,
            sort=sort,
            rating=rating,
            job_title=job_title,
            keyword=keyword,
            topic=topic,
            employment_status=employment_status,
            language=language,
            current_only=current_only,
            max_results=max_results,
            proxy_country=proxy_country,
        )

    def glassdoor_salaries(
        self,
        company: str,
        *,
        job_title: Optional[str] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Glassdoor company salaries.

        Returns a company's Glassdoor salary estimates by job title as JSON.
        Each row has `jobTitle`, `jobTitleId`, `basePay` and `totalPay`
        percentiles (`P10`, `P25`, `P50`, `P75`, `P90`), `currency`,
        `salaryCount` (salaries behind the estimate) and `mostRecent` (latest
        report). The response also carries `companyMeta` (name, rating, logo,
        website, industry, sector, headquarters, size, total salary count),
        `jobTitleCount` and `numPages`. Give `company` as a Glassdoor employer
        id, a Glassdoor company URL or a company name; narrow with `job_title`
        (Glassdoor's own job-title search) and collect up to `max_results` rows
        across pages, most-reported job titles first. Every field is always
        present and is `null` when Glassdoor does not show it. Billed per
        salary page fetched (10 rows per page).

        Args:
            company: The company: a Glassdoor employer id (e.g. '9079'), any
                Glassdoor company URL (e.g.
                'https://www.glassdoor.com/Overview/Working-at-Google-
                EI_IE9079.11,17.htm'), or a company name (e.g. 'Bank of
                America', matched with Glassdoor's company search).
            job_title: Narrow to job titles matching this text, using
                Glassdoor's own job-title search, e.g. 'software engineer'.
            max_results: How many job-title rows to return (10 per Glassdoor
                page, most-reported titles first). API default: 20.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Defaults to US, so pay is reported for the US
                market in USD.

        Calls ``POST /salaries/glassdoor``.
        """
        return self._post_json(
            "/salaries/glassdoor",
            company=company,
            job_title=job_title,
            max_results=max_results,
            proxy_country=proxy_country,
        )

    def naukri_jobs(
        self,
        keyword: str,
        *,
        location: Optional[str] = None,
        experience: Optional[int] = None,
        days: Optional[int] = None,
        remote: Optional[bool] = None,
        sort: Optional[str] = None,
        max_results: Optional[int] = None,
        page: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Naukri job listings.

        Searches Naukri (India's largest job board) for `keyword` in `location`
        and returns the job listings as JSON: `title`, `company`, `location`
        (with `workMode` hybrid / remote / on-site), `experience` (with parsed
        `experienceMinYears`/`experienceMaxYears`), `salary` (with parsed
        `min`/`max`), `skills`, `companyRating`, `reviewsCount`, a
        `description` snippet, `postedDate` and a clean job `url`. Filter with
        `location`, `experience` (years), `days` (posting age) and `remote`,
        sort with `sort`, and collect up to `max_results` across pages.

        Args:
            keyword: What to search, e.g. 'python developer' or 'data analyst'.
            location: City to search in, e.g. 'Bangalore' or 'Mumbai'.
            experience: Candidate experience in years (0-30).
            days: Max posting age in days: 1, 3, 7, 15, 30.
            remote: Only work-from-home / remote jobs. API default: false.
            sort: Ordering: relevance, date. API default: relevance.
            max_results: How many jobs to collect across pages (~20 per page).
                API default: 40.
            page: 1-based results page to start from. API default: 1.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank to let the API pick.

        Calls ``POST /jobs/naukri``.
        """
        return self._post_json(
            "/jobs/naukri",
            keyword=keyword,
            location=location,
            experience=experience,
            days=days,
            remote=remote,
            sort=sort,
            max_results=max_results,
            page=page,
            proxy_country=proxy_country,
        )

    def wellfound_jobs(
        self,
        role: Optional[str] = None,
        *,
        location: Optional[str] = None,
        remote: Optional[bool] = None,
        url: Optional[str] = None,
        page: Optional[int] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Wellfound startup jobs.

        Searches Wellfound (formerly AngelList Talent) startup jobs by `role`,
        `location` or remote `role` (or a Wellfound search `url`) and returns
        `jobs`: `title`, `url`, the full `description`, `compensation` with
        parsed `salary` (`min`, `max`, `currency`) and `equity` (`min`, `max`
        in %), `jobType` (`full-time`, `part-time`, `contract`, `internship`),
        `locations`, `remote`, `remotePolicy` (`ONSITE`, `REMOTE`,
        `ONSITE_OR_REMOTE`, `HYBRID`), `acceptedRemoteLocations`,
        `yearsExperienceMin`/`Max`, `postedAt` and the hiring `company`
        (`name`, `slug`, `url`, `tagline`, `companySize`, `stage`, `badges`). A
        listing page holds 20 companies with up to 3 matching jobs each; by
        default the call returns one page, with `max_results` it pages through
        up to that many jobs. Totals: `totalJobs`, `totalCompanies`,
        `pageCount`, `nextPage`. `mode=job&job=<url>` returns one job in full:
        description (text and HTML), salary with period, the same `jobType` and
        `remotePolicy` values (the page's wording in `remotePolicyText`, plus
        `wfhFlexible`), skills, `visaSponsorship`, `relocation`,
        `hiresRemotelyIn`, preferred timezones, hiring contact, posting date,
        and the company's size, markets, badges, funding and founders. Billed
        one unit per page fetched (`pagesFetched`).

        Args:
            role: Role to search, as text or Wellfound slug: 'software
                engineer', 'product-manager', 'data-scientist'.
            location: Location, as text or Wellfound slug: 'new york', 'san-
                francisco', 'london', 'berlin'.
            remote: Remote jobs only (needs role, no location). API default:
                false.
            url: A Wellfound search URL instead of role / location / remote:
                https://wellfound.com/role/l/software-engineer/san-francisco,
                /role/r/<role>, /location/<location>.
            page: 1-based listing page to start from (1-500); use `nextPage` of
                a previous response to continue. API default: 1.
            max_results: How many jobs to collect across pages (1-500).
                Default: the whole first page (20 companies with up to 3 jobs
                each, usually 30-60 jobs). Each page fetched is one billed
                unit.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank for the country chosen for the site.

        Calls ``POST /jobs/wellfound``.
        """
        return self._post_json(
            "/jobs/wellfound",
            mode='search',
            role=role,
            location=location,
            remote=remote,
            url=url,
            page=page,
            max_results=max_results,
            proxy_country=proxy_country,
        )

