    def wellfound_company(
        self,
        company: str,
        *,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Wellfound startup company profiles.

        Given a Wellfound `company` (slug like `stripe` or a
        wellfound.com/company/<slug> URL), returns its profile: `name`,
        `tagline`, `description`, `website` and social links, `companySize`,
        `stage`, `badges`, `markets`, `locations`, `companyTypes`, `hiring`,
        `openJobs` with `openJobsByRole`, `totalRaised`, `fundingRounds`
        (`type`, `date`, `valuation`), `founders` (name, profile URL, role,
        bio, location), `teamMembersCount`, `perks`, `media`, the first open
        `jobs` (with `jobsTotal`) and `similarCompanies`. Company profiles sit
        behind a Cloudflare challenge, so a call can take up to about a minute.
        `mode=search` lists Wellfound's startup directory by `location` or
        `industry` (10 companies per page, paged up to `max_results`) with
        website, description, markets, locations and open-job counts. Billed
        one unit per page fetched (`pagesFetched`).

        Args:
            company: mode=profile: the company slug ('stripe') or URL
                (https://wellfound.com/company/stripe).
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank for the country chosen for the site.

        Calls ``POST /companies/wellfound``.
        """
        return self._post_json(
            "/companies/wellfound",
            mode='profile',
            company=company,
            proxy_country=proxy_country,
        )

