    def product_hunt(
        self,
        *,
        mode: Optional[str] = None,
        query: Optional[str] = None,
        date: Optional[str] = None,
        topic: Optional[str] = None,
        slug: Optional[str] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Product Hunt launches, products, search and topics.

        Turns Product Hunt into JSON. `mode=leaderboard` returns a day's ranked
        launches (`date`=YYYY-MM-DD, or today) with votes, comments, topics and
        rank; `mode=search` returns products matching `query`; `mode=topic`
        returns products under a `topic` slug; `mode=detail` returns one
        product by `slug` with description, website, socials, review rating,
        followers and categories. Set `max_results` for the list modes.

        Args:
            mode: What to fetch: leaderboard, search, topic, detail. API
                default: leaderboard.
            query: Search terms (mode=search), e.g. 'ai chatbot'.
            date: Leaderboard day as YYYY-MM-DD (mode=leaderboard). Omit for
                today. Past days are finalised and ranked; today's board is
                live and not ranked yet.
            topic: Topic slug (mode=topic), e.g. 'artificial-intelligence'.
            slug: Product slug (mode=detail), e.g. 'notion'.
            max_results: Max products to return for list modes
                (leaderboard/search/topic). API default: 30.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank - Product Hunt is global and a forced
                country only hurts.

        Calls ``POST /products/producthunt``.
        """
        return self._post_json(
            "/products/producthunt",
            mode=mode,
            query=query,
            date=date,
            topic=topic,
            slug=slug,
            max_results=max_results,
            proxy_country=proxy_country,
        )

    def crunchbase_company(
        self,
        organization: str,
        *,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape a Crunchbase company profile, or search companies by name.

        With `organization` (a Crunchbase slug like 'stripe' or a
        crunchbase.com/organization/... URL) returns the organization as JSON:
        `name`, `slug`, `uuid`, `url`, `legalName`, `aliases`,
        `shortDescription`, `description`, `logo`, `website`, `headquarters`
        (city, region, country, continent), `operatingStatus`, `companyType`,
        `ipoStatus`, `stockSymbol` + `stockExchange`, `employeeRange`,
        `industries`, `industryGroups`, `hubTags`, CB `rank` with
        `rankDelta90d` (Crunchbase's 90-day trend score for the rank, from -10
        to 10: positive means the company moved up the ranking, toward #1),
        `growthScore` and `heatScore` (0-100) with `growthScoreDelta90d` and
        `heatScoreDelta90d` (their change in points over 90 days), `founders`,
        `lastFundingType`, counts (`numFundingRounds`, `numInvestors`,
        `numAcquisitions`, `numInvestments`, `numEmployeeProfiles` ...),
        `acquiredBy`, `owner`, the latest `fundingRounds` (type, investors,
        lead investors, each with `name`, `slug`, `url`, `type` and `image`
        like every other company or person reference), `investors`,
        `acquisitions`, `investments`, `exits`, `subOrganizations`, `keyPeople`
        (title, start date), `boardMembers`, `similarCompanies`, `products`,
        `contactEmail`, `phone`, `socialLinks`, `webTraffic` (`monthlyVisits`,
        and `monthlyVisitsChange`, the month-over-month change as a fraction:
        0.069 = +6.9%, -0.2 = -20%), `technology`, `predictions`, `events`
        (product launches, partnerships, awards, layoffs, key employee changes,
        legal proceedings, each with its press source), `offices` and recent
        `news`. Every one of the record's 73 keys is always present. Data
        Crunchbase shows only to paying users (founded / closed / IPO dates,
        funding totals, round dates and amounts, acquisition prices, exits,
        valuation) is null, and `paywalledFields` names the ones Crunchbase
        holds for this organization. With `query` instead, searches
        organizations by name and returns up to `max_results` (max 25) matches
        with `name`, `slug`, `url`, `shortDescription` and `logo`, plus the
        total `count` of matches. No Crunchbase login required.

        Args:
            organization: Crunchbase organization slug (the part after
                /organization/ in its profile URL, e.g. 'stripe' or 'tesla-
                motors') or the full profile URL. Either organization or query
                is required.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank to let the API pick.

        Calls ``POST /companies/crunchbase``.
        """
        return self._post_json(
            "/companies/crunchbase",
            organization=organization,
            proxy_country=proxy_country,
        )

