    def yelp_reviews(
        self,
        business: str,
        *,
        max_reviews: Optional[int] = None,
        page: Optional[int] = None,
        start: Optional[int] = None,
        sort: Optional[str] = None,
        language: Optional[str] = None,
        rating: Optional[str] = None,
        query: Optional[str] = None,
        since: Optional[str] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Yelp business reviews.

        Given a Yelp `business` (page URL, alias or business id), returns the
        `business` summary (`businessId`, `alias`, `name`, `url`, `rating`,
        `reviewCount`, `ratingHistogram`, `reviewsCountByLanguage`,
        `categories`, `city`, `region`) and its `reviews`: `id`, `url`,
        `rating`, `text`, `language`, `publishedDate`, `date`, `user` (`name`,
        `location`, `reviewCount`, `friendCount`, `photoCount`, `isElite`,
        `eliteYear`), `photos`, `videos`, `reactions` (`helpful`, `thanks`,
        `loveThis`, `ohNo`), `ownerResponse`, `checkIns` and the author's
        `previousReviews`. Sort like yelp.com (`relevance`, `newest`, `oldest`,
        `highest`, `lowest`, `elites`), filter by `language`, star `rating`, a
        search `query` or `since` a date, and page with `page` / `start` up to
        `max_reviews` per call. To continue, call again with `start` =
        `nextStart` while `hasMore` is true: `nextStart` is the exact offset
        where this call stopped. `nextPage` is only set when that offset falls
        on a page boundary (a multiple of 10) and is null otherwise, because a
        page number would repeat reviews already returned. Counts:
        `business.reviewCount` is the review count Yelp shows for the business;
        `business.ratingHistogram` and `business.reviewsCountByLanguage` count
        the reviews in every language, and Yelp updates them separately from
        `reviewCount`, so their sums can differ from it by a few;
        `totalResults` is how many reviews match this call's `language`,
        `rating` and `query` (the total that `start` pages through). A business
        with no reviews returns an empty list; an unknown alias or URL is a
        404. Billed one unit per 10 reviews returned (`pagesFetched`).

        Args:
            business: The business: its Yelp page URL
                (https://www.yelp.com/biz/gary-danko-san-francisco), its alias
                (gary-danko-san-francisco) or its business id
                (WavvLdfdP6g8aZTtbBQHTw, the `businessId` of /local/yelp
                results). An id is answered fastest; a URL or alias costs one
                business-page fetch first.
            max_reviews: How many reviews to return (1-500). API default: 20.
            page: 1-based Yelp review page to start from (10 reviews per page,
                like yelp.com's own pages; 1-1000). To continue a previous
                response, pass its `nextStart` as `start`. API default: 1.
            start: 0-based review offset to start from instead of `page`. Pass
                `nextStart` from a previous response to continue exactly where
                it stopped.
            sort: Review order, as yelp.com's "Sort by" menu: relevance,
                newest, oldest, highest, lowest, elites. `relevance` is Yelp's
                default order. API default: relevance.
            language: Reviews written in this language (two-letter code: en,
                fr, de, es, ...). Yelp lists one language at a time. Default:
                the language most of the business's reviews are in;
                `business.reviewsCountByLanguage` lists the others.
            rating: Only reviews with these star ratings, comma-separated (e.g.
                `1,2`).
            query: Only reviews that mention this phrase (yelp.com's review
                search).
            since: Only reviews written on or after this date (YYYY-MM-DD).
                With `sort=newest` paging stops at the first older review.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank: Yelp serves reviews the same to every
                country.

        Calls ``POST /local/yelp-reviews``.
        """
        return self._post_json(
            "/local/yelp-reviews",
            business=business,
            max_reviews=max_reviews,
            page=page,
            start=start,
            sort=sort,
            language=language,
            rating=rating,
            query=query,
            since=since,
            proxy_country=proxy_country,
        )

    def naver_place_search(
        self,
        query: str,
        *,
        longitude: Optional[float] = None,
        latitude: Optional[float] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Naver Map places.

        Naver Map (Naver Place), Korea's main local search.
        `mode=search&query=` returns up to 50 places (`results`): `id`, `name`,
        `category`, `businessType`, `address` / `roadAddress` / `jibunAddress`,
        `phone`, `latitude` / `longitude`, `rating`, `visitorReviewCount`,
        `blogReviewCount`, opening `status`, `microReview`, `popularMenus`,
        `options`, images, booking and Naver Pay flags, `hotelMinPrice`
        (stays), `representativePrice` (salons) and the place's Naver Map
        `url`, plus `totalResults`. `longitude` / `latitude` move the search
        centre (each place then carries its `distance`).
        `mode=details&place=<id or Naver Map link>` returns the `place` -
        addresses, phone, coordinates, `businessHours` per day, `description`,
        `directions`, `conveniences`, `facilities`, `keywords`, `menus` with
        prices, `photos`, `homepage` and `links`, `bookingUrl`,
        `subwayStations` and `reviewStats` (average rating, star distribution,
        keyword votes, themes) - with its first ten visitor `reviews` (`body`,
        `rating`, `created` / `createdDate`, `visitedAt`, `verifiedBy`,
        `keywords`, `media`, `reactions`, `author` stats, `ownerReply`) and its
        first `blogReviews` (blog and cafe posts). `sort=recent` returns the
        newest visitor reviews. Korean text is returned as is. One page per
        call, billed one unit.

        Args:
            query: What to search for (mode=search), in Korean or English: a
                category, a place name or both, e.g. '강남 맛집', '홍대 카페', '부산 호텔',
                'Gangnam cafe'.
            longitude: Search centre longitude (mode=search, with `latitude`),
                e.g. 127.0276. Naver ranks places around the centre, and each
                result then carries its `distance` from it.
            latitude: Search centre latitude (mode=search, with `longitude`),
                e.g. 37.4979.
            max_results: How many places to return (mode=search, 1-50). Naver
                answers one page of up to 50 places per search; move the search
                centre to reach other places. API default: 50.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'KR', 'US'). Leave blank for the country chosen for the site.

        Calls ``POST /maps/naver-place``.
        """
        return self._post_json(
            "/maps/naver-place",
            mode='search',
            query=query,
            longitude=longitude,
            latitude=latitude,
            max_results=max_results,
            proxy_country=proxy_country,
        )

    def naver_place_details(
        self,
        place: str,
        *,
        sort: Optional[str] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Naver Map places.

        Naver Map (Naver Place), Korea's main local search.
        `mode=search&query=` returns up to 50 places (`results`): `id`, `name`,
        `category`, `businessType`, `address` / `roadAddress` / `jibunAddress`,
        `phone`, `latitude` / `longitude`, `rating`, `visitorReviewCount`,
        `blogReviewCount`, opening `status`, `microReview`, `popularMenus`,
        `options`, images, booking and Naver Pay flags, `hotelMinPrice`
        (stays), `representativePrice` (salons) and the place's Naver Map
        `url`, plus `totalResults`. `longitude` / `latitude` move the search
        centre (each place then carries its `distance`).
        `mode=details&place=<id or Naver Map link>` returns the `place` -
        addresses, phone, coordinates, `businessHours` per day, `description`,
        `directions`, `conveniences`, `facilities`, `keywords`, `menus` with
        prices, `photos`, `homepage` and `links`, `bookingUrl`,
        `subwayStations` and `reviewStats` (average rating, star distribution,
        keyword votes, themes) - with its first ten visitor `reviews` (`body`,
        `rating`, `created` / `createdDate`, `visitedAt`, `verifiedBy`,
        `keywords`, `media`, `reactions`, `author` stats, `ownerReply`) and its
        first `blogReviews` (blog and cafe posts). `sort=recent` returns the
        newest visitor reviews. Korean text is returned as is. One page per
        call, billed one unit.

        Args:
            place: The place (mode=details): its Naver place id ('2097258400'),
                a Naver Map link
                (https://map.naver.com/p/entry/place/2097258400) or a Naver
                Place link
                (https://m.place.naver.com/restaurant/2097258400/home).
            sort: Visitor review order (mode=details): 'relevance' (Naver's
                default) or 'recent' (newest first). API default: relevance.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'KR', 'US'). Leave blank for the country chosen for the site.

        Calls ``POST /maps/naver-place``.
        """
        return self._post_json(
            "/maps/naver-place",
            mode='details',
            place=place,
            sort=sort,
            proxy_country=proxy_country,
        )

