    async def wish_search(
        self,
        query: str,
        *,
        page: Optional[int] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Wish product search.

        Searches Wish (wish.com) for `query` and returns `products`: `id`,
        `name`, `url`, `price`, `originalPrice` (crossed-out price, when
        discounted), `currency`, `priceText`, `priceUsd` (Wish's USD value,
        comparable across markets), `shipping`, `rating`, `ratingCount`,
        `numBought`, `inventory`, `colors`, `sizes`, `merchant` (`id`, `name`,
        `rating`, `ratingCount`, `feedback`, `country`), `originCountry`,
        `shipsFrom`, `tileText`, `isWishPick`, `position`, `image` and
        `thumbnail`, plus `totalResults` and `nextPage`. Wish shows the
        catalogue and prices of the request's country (`proxy_country`, default
        US). Collects up to `max_results` from `page` on, billed one unit per
        page.

        Args:
            query: What to search for, e.g. 'yoga mat' or 'phone case', or a
                wish.com/search/... link.
            page: 1-based results page to start from (1-300, up to 30 products
                per page). API default: 1.
            max_results: Products to collect across pages, 1-300. Each page
                fetched is billed one unit. API default: 30.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'GB', 'DE'). Wish shows the catalogue, prices and
                currency of that country. Default 'US' (prices in USD).

        Calls ``POST /marketplace/wish-search``.
        """
        return await self._post_json(
            "/marketplace/wish-search",
            query=query,
            page=page,
            max_results=max_results,
            proxy_country=proxy_country,
        )

