    async def tiktok_shop_search(
        self,
        q: Optional[str] = None,
        *,
        category: Optional[str] = None,
        max_results: Optional[int] = None,
    ) -> Any:
        """Search TikTok Shop products by keyword or category.

        Lists TikTok Shop (US) products for a keyword (`q`) or a category
        (`category`, URL or id). Each product card carries `productId`, `url`,
        `title`, `image`, `price` (current, original, discountPercent,
        currency, fromPrice), `rating`, `reviewCount`, `soldCount`, `brand`,
        `seller` (id, name, logo), promotion `labels` and, when TikTok binds
        one, the promoting `video` (id, url, author, play and like counts,
        `durationSeconds`). A keyword search also returns `relatedSearches` and
        `relatedCategories`; a category returns its `subcategories` and
        `breadcrumbs`. Up to 30 products (one page, one billed request). A
        keyword or category TikTok has no listing for returns 404.

        Args:
            q: Search keyword, e.g. 'led face mask' (or a TikTok Shop keyword
                URL like 'https://www.tiktok.com/shop/product/led-face-mask').
                Either this or `category`.
            category: List a category instead of a keyword: a category URL
                ('https://www.tiktok.com/shop/c/beauty-personal-care/601450')
                or its numeric id ('601450').
            max_results: Products to return (1-30). One page is read: a keyword
                lists up to 30 products, a category about 15. API default: 30.

        Calls ``POST /social/tiktok-shop-search``.
        """
        return await self._post_json(
            "/social/tiktok-shop-search",
            q=q,
            category=category,
            max_results=max_results,
        )

