    async def smyths_inventory(
        self,
        code: str,
        *,
        bundle: Optional[bool] = None,
    ) -> Any:
        """Smyths Toys UK product stock, price, details and listings.

        Smyths Toys UK (smythstoys.com) as JSON, in four modes. `mode=product`
        (the default when `code` is given) returns one product's stock and
        price as the JSON Smyths' own storefront reads (`/api/uk/en-
        gb/product/product-inventory`), unchanged: `code`, `type`, `prices`
        (`price`, `value`, `wasPrice`, `thenPrice`, `rrpPrice`,
        `discountedPercentage`), `hdSection` (home delivery: `stockStatus`,
        `stockMessage`, `isAvailableForDelivery`, `isPreOrder`,
        `expectedStockDate`, delivery messages), `ccSection` (click & collect:
        the same stock fields plus `storeName`, `deliveryMessage`,
        `storeClosed`), `ageSuitabilities`, `carrierType`, marketing messages
        and decals. `code` takes a product code (`225095`), a product or bundle
        page link or a product-inventory link; one product is one billed
        request. `mode=details&code=` returns the JSON Smyths' product page is
        built from (`/api/uk/en-gb/product`, a bundle's from `/api/uk/en-
        gb/b`), unchanged, one billed request: `name`, `brand`, `ean`,
        `description` (HTML), `webFeatures` (the key features list), the safety
        warnings `euWarning`, `safetyText`, `urgentSafetyTextHeading` and
        `urgentSafetyTextDescription`, `productImages` (the gallery:
        `thumbnail`, `original` and `zoom` per `galleryIndex`, videos as
        `youtubeUrl`), `prices`, `averageRating`, `numberOfReviews`,
        `breadcrumb`, `categoryHierarchy`, `ageSuitabilities`,
        `assemblyRequired` and more; a bundle adds `subProducts`. `url` and
        `breadcrumb` paths are relative to https://www.smythstoys.com/uk/en-gb.
        `mode=search&query=` and `mode=category&category=` find product codes:
        they return `products` (`code`, `name`, `url`, `prices` with the same
        fields, `currency`, `image`, `averageRating`, `productType` - `BUNDLE`
        for bundles - and `decals`) with `totalResults`, `totalPages` and
        `nextPage`, 60 per page; a category also returns its `title`,
        `breadcrumbs` and `subcategories` (`code`, `name`, `count`). Smyths'
        search returns its best 240 matches at most, a category every product
        it holds. Listings collect up to `max_results` from `page` on, billed
        one unit per page.

        Args:
            code: mode=product and mode=details: product code ('225095'),
                product or bundle page link, or product-inventory link.
            bundle: mode=product and mode=details: ask for a bundle. A bundle
                page link sets it, and a code Smyths does not answer as a
                product is asked again as a bundle. API default: false.

        Calls ``POST /marketplace/smyths-inventory``.
        """
        return await self._post_json(
            "/marketplace/smyths-inventory",
            mode='product',
            code=code,
            bundle=bundle,
        )

