    async def wellfound_jobs(
        self,
        role: Optional[str] = None,
        *,
        location: Optional[str] = None,
        remote: Optional[bool] = None,
        url: Optional[str] = None,
        page: Optional[int] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Wellfound startup jobs.

        Searches Wellfound (formerly AngelList Talent) startup jobs by `role`,
        `location` or remote `role` (or a Wellfound search `url`) and returns
        `jobs`: `title`, `url`, the full `description`, `compensation` with
        parsed `salary` (`min`, `max`, `currency`) and `equity` (`min`, `max`
        in %), `jobType` (`full-time`, `part-time`, `contract`, `internship`),
        `locations`, `remote`, `remotePolicy` (`ONSITE`, `REMOTE`,
        `ONSITE_OR_REMOTE`, `HYBRID`), `acceptedRemoteLocations`,
        `yearsExperienceMin`/`Max`, `postedAt` and the hiring `company`
        (`name`, `slug`, `url`, `tagline`, `companySize`, `stage`, `badges`). A
        listing page holds 20 companies with up to 3 matching jobs each; by
        default the call returns one page, with `max_results` it pages through
        up to that many jobs. Totals: `totalJobs`, `totalCompanies`,
        `pageCount`, `nextPage`. `mode=job&job=<url>` returns one job in full:
        description (text and HTML), salary with period, the same `jobType` and
        `remotePolicy` values (the page's wording in `remotePolicyText`, plus
        `wfhFlexible`), skills, `visaSponsorship`, `relocation`,
        `hiresRemotelyIn`, preferred timezones, hiring contact, posting date,
        and the company's size, markets, badges, funding and founders. Billed
        one unit per page fetched (`pagesFetched`).

        Args:
            role: Role to search, as text or Wellfound slug: 'software
                engineer', 'product-manager', 'data-scientist'.
            location: Location, as text or Wellfound slug: 'new york', 'san-
                francisco', 'london', 'berlin'.
            remote: Remote jobs only (needs role, no location). API default:
                false.
            url: A Wellfound search URL instead of role / location / remote:
                https://wellfound.com/role/l/software-engineer/san-francisco,
                /role/r/<role>, /location/<location>.
            page: 1-based listing page to start from (1-500); use `nextPage` of
                a previous response to continue. API default: 1.
            max_results: How many jobs to collect across pages (1-500).
                Default: the whole first page (20 companies with up to 3 jobs
                each, usually 30-60 jobs). Each page fetched is one billed
                unit.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank for the country chosen for the site.

        Calls ``POST /jobs/wellfound``.
        """
        return await self._post_json(
            "/jobs/wellfound",
            mode='search',
            role=role,
            location=location,
            remote=remote,
            url=url,
            page=page,
            max_results=max_results,
            proxy_country=proxy_country,
        )

