    async def capterra_reviews(
        self,
        product: str,
        *,
        slug: Optional[str] = None,
        page: Optional[int] = None,
        max_results: Optional[int] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Capterra software reviews.

        Given a Capterra `product` (numeric id like `135003`, `id/slug` like
        `135003/Slack`, or a capterra.com/p/<id>/<slug>/ URL), returns the
        product summary (`name`, `vendor`, `rating`, `reviewCount`,
        sub-`ratings` `easeOfUse`, `customerSupport` (Capterra's "Customer
        Service" rating), `features` and `valueForMoney`, `categories`,
        `description`, `pricing`) and its `reviews`: `title`, `rating`, the
        same sub-`ratings` with `likelihoodToRecommend` (0-10), `date`,
        `reviewer` (job title, industry, company size, time used, validations),
        `comments`, `pros`, `cons`, `reasonsForChoosing`, `reasonsForSwitching`
        with `alternativesConsidered` / `switchedFrom`, `advice`, the incentive
        badges (`incentive`, `incentivized`, `vendorReferred`, `reviewSource`),
        `source` (Capterra, GetApp or Software Advice) and `vendorResponse`.
        Pages through Capterra's review pages up to `max_results` (25 per page,
        at most 100 pages, in Capterra's "Most Helpful" order). A product with
        only a few reviews has no review pages; its reviews come from its
        profile in one page. A product without reviews answers 200 with an
        empty `reviews` list. `mode=search&query=` searches Capterra's product
        catalog (one page of up to 20 products, plus matching categories). A
        bare product id costs one extra fetch the first time a page past the
        first is asked for (Capterra redirects it to the canonical slug);
        `id/slug` (echoed in `query`) avoids it. Billed one unit per page
        fetched (`pagesFetched`).

        Args:
            product: Capterra product: its numeric id ('135003'), 'id/slug'
                ('135003/Slack') or a capterra.com product URL such as
                https://www.capterra.com/p/135003/Slack/reviews/. Required
                unless mode=search.
            slug: Optional product slug ('Slack') to go with a bare id.
                Capterra finds the product by id alone; the canonical slug is
                returned.
            page: 1-based review page to start from: 25 reviews per page, at
                most 100 (Capterra's limit per product). Use the `nextPage` of
                a previous response to continue. API default: 1.
            max_results: How many reviews to collect across pages (1-500,
                default 25); each page fetched is one billed unit. With
                mode=search, how many products (1-20, default 20; one page).
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank for the country chosen for the site.

        Calls ``POST /reviews/capterra``.
        """
        return await self._post_json(
            "/reviews/capterra",
            mode='reviews',
            product=product,
            slug=slug,
            page=page,
            max_results=max_results,
            proxy_country=proxy_country,
        )

