    async def app_store_app(
        self,
        app_id: str,
        *,
        country: Optional[str] = None,
        lang: Optional[str] = None,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Scrape Apple App Store app details, search and reviews.

        Scrapes the Apple App Store. `mode=app` with `app_id` (numeric id,
        `id310633997`, an apps.apple.com URL or a bundle id) returns one app's
        full detail: title, `subtitle`, developer (id, store page, website),
        price / currency / `free`, `rating`, `ratingsCount` and the star
        `histogram`, `contentRating`, genres, `releaseDate`, `updated`,
        `version`, `releaseNotes` and `versionHistory`, `size` in bytes,
        `minimumOsVersion`, `languages`, description, screenshots, icon,
        `inAppPurchases`, `privacy` labels, `chartRank` and `similarApps`.
        `mode=search` with `q` returns matching apps (up to 200).
        `mode=reviews` returns customer reviews (title, text, rating, author,
        date, app version, helpful votes), newest or most helpful first; Apple
        serves 50 per page and 500 per country. `country` picks the storefront.
        mode=reviews is billed one request per review page fetched
        (`pagesFetched`).

        Args:
            app_id: App for mode=app / mode=reviews: the numeric App Store id
                ('310633997'), 'id310633997', an apps.apple.com app URL, or a
                bundle id ('net.whatsapp.WhatsApp').
            country: App Store country (ISO-2), e.g. 'us', 'gb', 'de'. Prices,
                ratings and reviews are per country. Default: the country in an
                app URL, else 'us'.
            lang: Listing language for mode=app / mode=search, e.g. 'fr' or
                'fr-CA' (for countries whose store has several languages).
                Default: the store's own.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Leave blank to let the API pick.

        Calls ``POST /apps/app-store``.
        """
        return await self._post_json(
            "/apps/app-store",
            mode='app',
            app_id=app_id,
            country=country,
            lang=lang,
            proxy_country=proxy_country,
        )

