    async def similarweb_overview(
        self,
        domain: str,
        *,
        proxy_country: Optional[str] = None,
    ) -> Any:
        """Get a website's Similarweb traffic overview.

        Returns Similarweb's public traffic overview for `domain` as JSON:
        `globalRank`, `countryRank` (with `country`), `categoryRank` (with
        `category`) and their month-over-month changes; `totalVisits` for the
        latest month with `visitsChangePercent`; `bounceRate`, `pagesPerVisit`,
        `avgVisitDuration`/`avgVisitDurationSeconds`; `visitsHistory` (the last
        3 months - earlier months are derived from Similarweb's own month-over-
        month change) and `rankHistory`; `trafficSources` (channel shares -
        Similarweb's free page reveals only some, the rest are null);
        `topCountries`; `demographics` (gender, age groups); `competitors`
        (similar sites with affinity); `search` (organic/paid split and top
        keywords); `socialNetworks`, `referrals`, `outgoingLinks`,
        `displayAds`; `technologies`; `audienceInterests`; and the `company`
        profile. `snapshotDate` is the month the data describes. A domain
        Similarweb has no page for returns `found: false` with the same keys
        set to null/empty; a known domain too small to estimate returns
        `hasTrafficData: false`.

        Args:
            domain: Website to look up: a bare domain ('github.com'), a URL
                ('https://www.github.com/about'), or a Similarweb page URL. A
                leading 'www.' is dropped; other subdomains ('docs.python.org')
                are kept.
            proxy_country: Proxy country the request is sent from (ISO-2, e.g.
                'US', 'DE'). Optional.

        Calls ``POST /seo/similarweb``.
        """
        return await self._post_json(
            "/seo/similarweb",
            domain=domain,
            proxy_country=proxy_country,
        )

    async def ahrefs(
        self,
        tool: str,
        *,
        target: Optional[str] = None,
        keyword: Optional[str] = None,
        country: Optional[str] = None,
        mode: Optional[str] = None,
        protocol: Optional[str] = None,
        questions: Optional[bool] = None,
    ) -> Any:
        """Run Ahrefs' free SEO tools (DR, backlinks, traffic, keywords, KD,
        SERP).

        Ahrefs' free SEO tools as JSON, without an Ahrefs account.
        `tool=authority&target=<domain>`: `domainRating`, `backlinks`,
        `referringDomains`, `dofollowBacklinksPercent`,
        `dofollowReferringDomainsPercent`. `tool=backlinks`: the same plus
        `topBacklinks` (`urlFrom`, `urlTo`, `title`, `anchor`,
        `textBefore`/`textAfter`, `domainRating`). `tool=traffic`:
        `organicTraffic`, `trafficValueUsd`, `trafficHistory`, `topPages`,
        `topCountries`, `topKeywords` (`country` narrows it to one market).
        `tool=broken-links`: `inbound` broken backlinks and `outbound` broken
        links on the site's pages. `tool=keyword-difficulty&keyword=<phrase>`:
        `difficulty` (0-100), `referringDomainsToRank` and the SERP `results`.
        `tool=keywords`: `ideas` and `questionIdeas` with `difficulty` and
        `volume` buckets, plus totals (Google). `tool=serp`: the top Google
        `results` (organic with `metrics` - DR, UR, backlinks, referring
        domains, traffic, value, keywords - plus AI overview, questions,
        shopping, local and news blocks). Domain tools take `mode` (subdomains,
        domain, prefix, exact). One call, one unit.

        Args:
            tool: Which Ahrefs free tool to run: 'authority' (Domain Rating),
                'backlinks', 'traffic', 'broken-links' (these take `target`),
                'keyword-difficulty', 'keywords' (keyword ideas), 'serp' (these
                take `keyword`).
            target: Domain or URL for the domain tools, e.g. 'github.com' or
                'https://github.com/features'.
            keyword: Search phrase for the keyword tools, e.g. 'running shoes'.
            country: Two-letter market code. Keyword tools: the search market
                (default 'us'). traffic: limits the estimate to that country
                (default: worldwide). Not used by the other domain tools.
            mode: Target scope for the domain tools: 'subdomains' (the domain
                with all its subdomains), 'domain' (without subdomains),
                'prefix' (everything under the URL) or 'exact' (that URL only).
                API default: subdomains.
            protocol: traffic only: 'both', 'http' or 'https'. API default:
                both.
            questions: keywords only: also return question ideas. API default:
                true.

        Calls ``POST /seo/ahrefs``.
        """
        return await self._post_json(
            "/seo/ahrefs",
            tool=tool,
            target=target,
            keyword=keyword,
            country=country,
            mode=mode,
            protocol=protocol,
            questions=questions,
        )

    async def semrush_overview(
        self,
        domain: str,
        *,
        report: Optional[str] = None,
    ) -> Any:
        """Get a website's Semrush overview (Authority Score, traffic, backlinks).

        Semrush's public website data for `domain`, without a Semrush account.
        `report=overview` (default): `authorityScore`, `globalRank`,
        `countryRank`, `categoryRank`, `visits` with `visitsChangePercent` and
        `visitsHistory` (desktop/mobile), `pagesPerVisit`, `timeOnSiteSeconds`,
        `bounceRate`, `searchTraffic` (organic and paid with history),
        `backlinks` (backlinks, referring domains, Google penalty risk,
        history), `topKeywords` (position, search volume, CPC, traffic share,
        intent), `topCountries`, `competitors`, `trafficSources` (incoming and
        outgoing) and `aiTraffic` (visits from AI assistants).
        `report=competitors`: the domain's competitors, each with Authority
        Score, ranks, visits and engagement. Semrush publishes these pages for
        about 200k of the most visited sites; any other domain returns `found:
        false`. One call, one unit.

        Args:
            domain: Website to look up: a domain ('github.com'), a URL
                ('https://www.github.com/about') or a Semrush website page URL.
                A leading 'www.' is dropped; other subdomains are kept.
            report: 'overview' (traffic, rank, search traffic, backlinks,
                keywords, countries, competitors, sources) or 'competitors'
                (the competitor list with each one's ranks, visits and
                engagement). API default: overview.

        Calls ``POST /seo/semrush``.
        """
        return await self._post_json(
            "/seo/semrush",
            domain=domain,
            report=report,
        )
